# 毕业设计 Step10: Agent 工具系统
from datetime import datetime


class Tool:
    def __init__(self, name: str, description: str, func, keywords: list):
        self.name = name
        self.description = description  # 给LLM看的: 干什么+什么时候用
        self.func = func
        self.keywords = keywords        # 规则路由用的触发词


class ToolRegistry:
    def __init__(self):
        self.tools = []

    def register(self, tool: Tool):
        self.tools.append(tool)

    def route(self, query: str) -> str:
        """规则路由: 命中关键词走对应工具, 否则走知识库。"""
        for tool in self.tools:
            if tool.name != "kb_search" and any(kw in query for kw in tool.keywords):
                return f"[{tool.name}] {tool.func(query)}"
        kb = next(t for t in self.tools if t.name == "kb_search")
        return f"[{kb.name}] {kb.func(query)}"


# ===== 定义三个工具 =====
def kb_search(q: str) -> str:
    return f"知识库回答: 注意力机制是对输入加权关注的机制(来源: transformer.pdf p3)"

def calculator(q: str) -> str:
    expr = "".join(c for c in q if c in "0123456789+-*/.() ")
    try:
        return f"计算结果: {eval(expr)}"  # 教学环境; 生产用 ast 白名单解析!
    except Exception as e:
        return f"无法计算: {e}"

def current_time(q: str) -> str:
    return f"当前时间: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}"


registry = ToolRegistry()
registry.register(Tool("kb_search", "查询知识库回答专业问题", kb_search, []))
registry.register(Tool("calculator", "数学计算", calculator, ["计算", "多少", "等于", "+", "*"]))
registry.register(Tool("get_time", "查询当前时间", current_time, ["时间", "几点", "现在"]))

for q in ["什么是注意力机制?", "帮我计算 128 * 46", "现在几点了?"]:
    print(f"Q: {q}\n  → {registry.route(q)}")

