# 毕业设计 Step11: ReAct 推理循环
class ReActAgent:
    """简化ReAct: 显式记录 Thought/Action/Observation, 多步推理直到Final Answer。"""

    def __init__(self, tools: dict, max_iterations: int = 5):
        self.tools = tools
        self.max_iterations = max_iterations  # 护栏: 防死循环

    def _decide(self, question: str, history: list) -> tuple:
        """模拟LLM决策: 真实环境把history发给DeepSeek让它输出Action。
        这里用规则模拟一个'查两次再总结'的决策序列。"""
        n = len(history)
        if "对比" in question and n == 0:
            return ("action", "kb_search", "A文档对注意力的描述")
        if "对比" in question and n == 1:
            return ("action", "kb_search", "B文档对注意力的描述")
        return ("final", None, "综合两份资料: A侧重数学定义, B侧重工程实现, 二者互补")

    def run(self, question: str) -> str:
        history = []
        for step in range(self.max_iterations):
            kind, action, payload = self._decide(question, history)
            if kind == "final":
                print(f"Step {step+1} Thought: 信息足够, 给出最终答案")
                return payload
            print(f"Step {step+1} Thought: 需要调用 {action}")
            print(f"         Action: {action}(\"{payload}\")")
            observation = self.tools[action](payload)
            print(f"         Observation: {observation}")
            history.append({"action": action, "observation": observation})
        return "达到最大推理步数, 基于已有信息回答(兜底)"


def kb_search(q: str) -> str:
    data = {"A文档": "注意力是QKV点积加权的数学运算", "B文档": "注意力在工程上用flash-attention优化显存"}
    for k, v in data.items():
        if k[0] in q:
            return f"{k}: {v}"
    return "未找到"


agent = ReActAgent(tools={"kb_search": kb_search}, max_iterations=5)
print("最终答案:", agent.run("对比A文档和B文档对注意力的描述"))

