# 毕业设计 Step12: Agent 对话记忆(滑动窗口)
class ConversationMemory:
    """滑动窗口记忆: 只保留最近 window 轮, 防止token爆炸。"""

    def __init__(self, window: int = 3):
        self.window = window
        self.history = []  # [{"role": "user"/"assistant", "content": str}]

    def add(self, role: str, content: str):
        self.history.append({"role": role, "content": content})
        # 超出窗口丢弃最老的(一轮=user+assistant两条, 所以乘2)
        if len(self.history) > self.window * 2:
            self.history = self.history[-self.window * 2:]

    def build_context(self) -> str:
        """把历史渲染成prompt上下文, LLM靠它理解'它'这类指代。"""
        return "\n".join(f"{m['role']}: {m['content']}" for m in self.history)


def mock_llm_with_memory(question: str, context: str) -> str:
    """模拟LLM: 有上下文就能解指代。真实环境把context+question发给DeepSeek。"""
    if "它" in question and "Transformer" in context:
        return "Transformer 由 Google 在 2017 年论文《Attention Is All You Need》中提出"
    if "注意力" in question:
        return "Transformer 的核心是注意力机制"
    return "我需要更多上下文"


memory = ConversationMemory(window=3)
dialog = [
    "什么是 Transformer 的核心?",
    "它的作者是谁?",      # 指代消解: 靠memory知道"它"=Transformer
    "那篇论文哪年发的?",    # 又换了个指代
]
for q in dialog:
    ctx = memory.build_context()
    answer = mock_llm_with_memory(q, ctx)
    print(f"用户: {q}")
    print(f"Agent: {answer}")
    memory.add("user", q)
    memory.add("assistant", answer)
    print(f"  (记忆窗口现有 {len(memory.history)} 条)")
